package atomic

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
	"strings"
	"sync"
)

// The embedded data (data/atomic.json.gz, generated by the scratchpad tool gwe-tools/gen_atomic.py
// from the editor config of the upstream editor with the atomic experiments on): the style schema,
// every atomic element/widget type with its props schema, base styles and main template, and the
// Twig templates.

//go:embed data/atomic.json.gz
var atomicData []byte

// PropType is a node of a props schema (the editor config's JSON serialisation of a Prop_Type).
type PropType struct {
	Kind     string // plain, string, number, boolean, object, array, union
	Key      string // the $$type it accepts
	Default  any
	Settings *Map
	Shape    *Schema              // object kinds
	Item     *PropType            // array kinds
	Types    map[string]*PropType // union kinds, by $$type
}

// Schema is an ordered set of named prop types.
type Schema struct {
	Keys  []string
	Props map[string]*PropType
}

func parseSchema(v any) *Schema {
	s := &Schema{Props: map[string]*PropType{}}
	m := asMap(v)
	for _, k := range m.Keys() {
		s.Keys = append(s.Keys, k)
		s.Props[k] = parsePropType(m.Get(k))
	}
	return s
}

func parsePropType(v any) *PropType {
	m := asMap(v)
	if m == nil {
		return &PropType{Kind: "plain"}
	}
	p := &PropType{Kind: phpString(m.Get("kind")), Key: phpString(m.Get("key")), Default: m.Get("default"), Settings: asMap(m.Get("settings"))}
	switch p.Kind {
	case "object":
		p.Shape = parseSchema(m.Get("shape"))
	case "array":
		p.Item = parsePropType(m.Get("item_prop_type"))
	case "union":
		p.Types = map[string]*PropType{}
		tm := asMap(m.Get("prop_types"))
		for _, k := range tm.Keys() {
			p.Types[k] = parsePropType(tm.Get(k))
		}
	}
	return p
}

// ElementType describes an atomic element or widget.
type ElementType struct {
	Name        string
	Widget      bool // elType "widget" (vs an element type of its own)
	Schema      *Schema
	BaseStyles  *Map // style id → style definition
	Dictionary  *Map // base style key → class name
	Template    string
	DefaultTag  string
	FollowsLink bool
}

type registry struct {
	order       []string
	elements    map[string]*ElementType
	styleSchema *Schema
	twig        *TwigEnv
	err         error
}

var (
	regOnce sync.Once
	reg     *registry
)

func data() *registry {
	regOnce.Do(func() {
		reg = &registry{elements: map[string]*ElementType{}}
		zr, err := gzip.NewReader(bytes.NewReader(atomicData))
		if err != nil {
			reg.err = err
			return
		}
		raw, err := io.ReadAll(zr)
		if err != nil {
			reg.err = err
			return
		}
		v, err := Decode(raw)
		if err != nil {
			reg.err = err
			return
		}
		root := asMap(v)
		reg.styleSchema = parseSchema(root.Get("styles_schema"))
		els := asMap(root.Get("elements"))
		for _, k := range els.Keys() {
			e := asMap(els.Get(k))
			reg.elements[k] = &ElementType{
				Name: k, Widget: e.Get("widget") == true, Schema: parseSchema(e.Get("schema")),
				BaseStyles: asMap(e.Get("base_styles")), Dictionary: asMap(e.Get("dictionary")),
				Template: phpString(e.Get("template")), DefaultTag: phpString(e.Get("default_tag")),
				FollowsLink: e.Get("follows_link") != false,
			}
		}
		for _, k := range listOf(root.Get("order")) {
			reg.order = append(reg.order, phpString(k))
		}
		sources := map[string]string{}
		tm := asMap(root.Get("templates"))
		for _, k := range tm.Keys() {
			sources[k] = phpString(tm.Get(k))
		}
		reg.twig, reg.err = NewTwigEnv(sources)
		if reg.twig != nil {
			reg.twig.Escapers["full_url"] = escURL
			reg.twig.Escapers["html_tag"] = validateHTMLTag
		}
	})
	return reg
}

// Lookup returns an atomic element type ("e-heading", "e-flexbox", ...), or nil.
func Lookup(name string) *ElementType {
	if !strings.HasPrefix(name, "e-") {
		return nil
	}
	return data().elements[name]
}

// IsAtomic reports whether an element (elType, widgetType) is atomic.
func IsAtomic(elType, widgetType string) bool {
	if elType == "widget" {
		return Lookup(widgetType) != nil
	}
	return Lookup(elType) != nil
}

// StyleSchema is the style props schema.
func StyleSchema() *Schema { return data().styleSchema }

// Err reports a failure to load the embedded data.
func Err() error { return data().err }
